import { createContext, useContext, useEffect, useState, type ReactNode } from "react"

export interface User {
  id: string
  email: string
  name?: string
  nombre: string
  apellido: string
  telefono?: string
  direccion?: string
  role?: "admin" | "user"
  rol?: "CLIENTE" | "ADMIN" | "FARMACEUTICO"
  fechaRegistro?: string
  activo?: boolean
}

export interface AuthState {
  user: User | null
  isLoading: boolean
  isAuthenticated: boolean
}

const API_URL = "http://localhost:8080/api/usuarios"
const LOGOUT_URL = "http://localhost:8080/logout"

export const authService = {
  async login(email: string, password: string): Promise<{ user: User; token: string }> {
    const response = await fetch(`${API_URL}/login`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ email, password }),
    })

    if (!response.ok) {
      const errorText = await response.text()
      throw new Error(`Error en el login: ${errorText || response.statusText}`)
    }

    const data = await response.json()
    const token = data.token || "no-token"
    const user = data.usuario || data.user || data

    localStorage.setItem("auth-token", token)
    localStorage.setItem("user", JSON.stringify(user))

    // Disparar evento para que el carrito se sincronice
    window.dispatchEvent(new Event("user-login"))

    return { user, token }
  },

  async register(userData: {
    email: string
    password: string
    nombre: string
    apellido: string
    telefono?: string
  }): Promise<{ user: User; token: string }> {
    const response = await fetch(`${API_URL}/registro`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        nombre: userData.nombre,
        apellido: userData.apellido,
        email: userData.email,
        telefono: userData.telefono,
        contraseña: userData.password,
      }),
    })

    if (!response.ok) {
      const errorText = await response.text()
      throw new Error(`Error en el registro: ${errorText || response.statusText}`)
    }

    const user = await response.json()
    const token = "registro-token"

    localStorage.setItem("auth-token", token)
    localStorage.setItem("user", JSON.stringify(user))

    // Disparar evento para que el carrito se sincronice
    window.dispatchEvent(new Event("user-login"))

    return { user, token }
  },

  async logout(): Promise<void> {
    try {
      const token = this.getToken()
      if (token) {
        await fetch(LOGOUT_URL, {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            "Authorization": `Bearer ${token}`
          },
        })
      }
